//! Actual trusted activation of contextual native BUTTONs preserves nearby App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn range_fragment_buttons_actual_app_trusted_activation_disabled_paint_and_editor(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-range-buttons-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><form id=f><input id=resetedit value=seed style="position:absolute;left:20px;top:180px;width:150px;height:30px"><div id=mount></div></form><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Construct button</button><div id=destination></div><script>
var mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual construction pointer';var r=document.createRange();r.selectNodeContents(mount);var fragment=r.createContextualFragment('<button id=created type=button name=action value=before style="position:absolute;left:20px;top:80px;width:150px;height:30px">Run <b>now</b></button><button id=blocked type=button disabled style="position:absolute;left:20px;top:130px;width:150px;height:30px">Disabled</button><button id=resetter type=reset style="position:absolute;left:20px;top:230px;width:150px;height:30px">Reset</button>'),button=fragment.firstChild,blocked=fragment.childNodes[1],resetter=fragment.lastChild;if(button.ownerDocument!==document||button.type!=='button'||button.value!=='before'||button.form!==null||button.isConnected||!blocked.disabled||watch.takeRecords().length)throw 'real detached native buttons';button.value='edited';mount.appendChild(fragment);var records=watch.takeRecords();if(fragment.firstChild!==null||mount.firstChild!==button||document.getElementById('created')!==button||button.value!=='edited'||!button.isConnected||records.length!==1||records[0].addedNodes.length!==3||records[0].addedNodes[0]!==button||records[0].addedNodes[1]!==blocked)throw 'button fragment identity and records';button.onclick=function(e){if(!e.isTrusted||this!==button||this.value!=='edited')throw 'actual new native button';document.getElementById('paint').className='ready';document.title='Range button activated';};blocked.onclick=function(){throw 'disabled native button activated';};resetter.onclick=function(e){if(!e.isTrusted||this!==resetter||this.form!==document.getElementById('f'))throw 'actual reset pointer';document.title='Range button reset';};document.getElementById('resetedit').value='changed';if(document.getElementById('neighbor').value!=='edited neighbor')throw 'native neighbor';document.title='Range buttons connected';};
</script></body></html>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Range buttons connected");
 let created=node(&app,"created");let blocked=node(&app,"blocked");let control=&app.forms.controls[&created];assert_eq!(control.kind,crate::forms::Kind::Button);assert_eq!(control.caption,"Run now");assert_eq!(control.value.text(),"edited");assert_eq!(control.owner,Some(node(&app,"f")));assert!(app.forms.controls[&blocked].disabled);
 for target in [blocked,created]{
  let rect=app.page.controls.iter().find(|r|r.node==target).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,if target==blocked{"Range buttons connected"}else{"Range button activated"});
 }
 let resetter=node(&app,"resetter");assert_eq!(app.forms.controls[&node(&app,"resetedit")].value.text(),"changed");let rect=app.page.controls.iter().find(|r|r.node==resetter).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Range button reset");assert_eq!(app.forms.controls[&node(&app,"resetedit")].value.text(),"seed");
 let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}
